254	    /**
255	     * The owner's membership level, a number from 1 to 3 derived from the owner's own fields as
256	     * captured at creation time. It starts at 1, gains 1 when an email is present, gains a further
257	     * 1 when the owner has no namesakes ({@code namesakeCount} is 0), and is capped at 3. Level 4
258	     * is reserved for tenure and is never produced here.
259	     */
260	    @Transient
261	    public Integer getMembershipLevel() {
262	        int level = 1;
263	        boolean hasEmail = this.email != null && !this.email.isBlank();
264	        if (hasEmail) {
265	            level++;
266	        }
267	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
268	        if (noNamesakes) {
269	            level++;
270	        }
271	        return Math.min(level, 3);
272	    }
