334	    /**
335	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
336	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
337	     * is the stored E.164 value, the email is the stored lower-cased value (empty when absent) and
338	     * the household segment is the deterministic {@code householdId} derived from the last name and
339	     * postcode (empty only when no household id has been assigned). Two owners are duplicates only
340	     * when their whole identity keys are equal.
341	     */
342	    @Transient
343	    public String getIdentityKey() {
344	        String telephonePart = this.telephone == null ? "" : this.telephone;
345	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
346	        String householdPart = this.householdId == null ? "" : this.householdId;
347	        return telephonePart + "|" + emailPart + "|" + householdPart;
348	    }
