434	    /**
435	     * Return the Pet with the given name, or null if none found for this Owner.
436	     *
437	     * @param name to test
438	     * @return true if pet name is already in use
439	     */
440	    public Pet getPet(String name, boolean ignoreNew) {
441	        name = name.toLowerCase();
442	        for (Pet pet : getPetsInternal()) {
443	            if (!ignoreNew || !pet.isNew()) {
444	                String compName = pet.getName();
445	                compName = compName.toLowerCase();
446	                if (compName.equals(name)) {
447	                    return pet;
448	                }
449	            }
450	        }
451	        return null;
452	    }
